function validate([num]) {
  if (!Number.isInteger(num) || num < 1 || num > 10000) return 'num is an integer from 1 to 10^4.';
  if (!/^[69]+$/.test(String(num))) return 'num may only use the digits 6 and 9.';
  return null;
}

