function maximum69Number(num) {
  let place = 1;
  let highestSix = 0;
  let rest = num;

  while (rest > 0) {
    if (rest % 10 === 6) {
      highestSix = place;
    }
    rest = Math.floor(rest / 10);
    place *= 10;
  }

  return num + 3 * highestSix;
}

