function maximum69Number(num) {
  const digits = String(num).split('');
  let best = num;
  for (let i = 0; i < digits.length; i++) {
    const copy = digits.slice();
    copy[i] = copy[i] === '6' ? '9' : '6';
    best = Math.max(best, Number(copy.join('')));
  }
  return best;
}

